import{c as r,Q as a,j as t,m as o}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"From Recall to Forgetting: Benchmarking Long-Term Memory for Personalized Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.20006","title":"From Recall to Forgetting: Benchmarking Long-Term Memory for Personalized Agents","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2604.20006,"authors":["Md Nayem Uddin","Kumar Shubham","Eduardo Blanco","Chitta Baral","Gengyu Wang"],"domains":["cs.CL"],"html":"https://arxiv.org/html/2604.20006v1","pdf_path":"pdfs/2604.20006.pdf","published_date":"2026-04-21T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-21-recall-to-forgetting-long-term-memory-benchmark-2604-20006.md","filePath":"research/papers/2026-04-21-recall-to-forgetting-long-term-memory-benchmark-2604-20006.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-04-21-recall-to-forgetting-long-term-memory-benchmark-2604-20006.md"};function i(s,e,l,m,c,g){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="from-recall-to-forgetting-benchmarking-long-term-memory-for-personalized-agents" tabindex="-1">From Recall to Forgetting: Benchmarking Long-Term Memory for Personalized Agents <a class="header-anchor" href="#from-recall-to-forgetting-benchmarking-long-term-memory-for-personalized-agents" aria-label="Permalink to &quot;From Recall to Forgetting: Benchmarking Long-Term Memory for Personalized Agents&quot;">​</a></h1><p><strong>Authors</strong>: Md Nayem Uddin, Kumar Shubham, Eduardo Blanco, Chitta Baral, Gengyu Wang <strong>Published</strong>: April 21, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2604.20006" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.20006</a> · <a href="https://arxiv.org/html/2604.20006v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2604.20006 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2604.20006" target="_blank" rel="noreferrer">research/papers/pdfs/2604.20006.pdf</a> (28 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Personalized agents that interact with users over long periods must maintain persistent memory across sessions and update it as circumstances change. However, existing benchmarks predominantly frame long-term memory evaluation as fact retrieval from past conversations, providing limited insight into agents&#39; ability to consolidate memory over time or handle frequent knowledge updates. We introduce Memora, a long-term memory benchmark spanning weeks to months long user conversations. The benchmark evaluates three memory-grounded tasks: remembering, reasoning, and recommending. To ensure data quality, we employ automated memory-grounding checks and human evaluation. We further introduce Forgetting-Aware Memory Accuracy (FAMA), a metric that penalizes reliance on obsolete or invalidated memory when evaluating long-term memory. Evaluations of four LLMs and six memory agents reveal frequent reuse of invalid memories and failures to reconcile evolving memories. Memory agents offer marginal improvements, exposing shortcomings in long-term memory for personalized agents.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 Memora：跨「數週到數月」對話的長期記憶 benchmark，評測三類 memory-grounded 任務——remembering、reasoning、recommending。</li><li>提出 FAMA（Forgetting-Aware Memory Accuracy）指標：對「依賴過時/已失效記憶」加以懲罰，超越單純 fact retrieval 的評估框架。</li><li>以 automated memory-grounding check + 人工評估保證資料品質。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>評測 4 個 LLM + 6 個 memory agent：普遍發現「重複使用無效記憶」與「無法調和演變中的記憶」。</li><li>memory agent 僅帶來邊際改善，暴露 personalized agent 長期記憶的根本缺陷。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未於 abstract 列明確 limitation；判斷弱點：benchmark 規模/語言覆蓋未在 abstract 量化；FAMA 對「obsolete」的界定依賴標註，可能引入主觀性。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>FAMA「懲罰沿用失效記憶」直接對應 core.md RECORD 與本庫 MEMORY/LESSONS 的核心風險：compact 後沿用過時決策 → context collapse；呼應 context-management「compact 後自檢③ 最近工具結果未失真」。</li><li>「無法調和演變中的記憶」對應 2606.09483 的 belief revision／supersedes chain——本批論文共同指向「記憶需可失效、可覆寫」。</li><li>⚠️ 落地門檻：本庫無自動 forgetting 機制；可作為設計 memory-compactor 整合 gate 時「過時資訊偵測」的評估視角，非現成指標實作。</li></ul>',16)])])}const u=r(n,[["render",i]]);export{h as __pageData,u as default};
